using bf16 = __nv_bfloat16;

__device__ __forceinline__ uint32_t smem_addr16(const void* base, int row, int col8) {
    // LINEAR (no swizzle) for semantics testing
    const char* p = (const char*)base + row * 256 + col8 * 16;
    return (uint32_t)__cvta_generic_to_shared(p);
}

// plain x4: 16 rows x 16 cols (A fragment layout), r0 = first row, c0 = first col (16-aligned)
