    uint32_t t[2];
    asm volatile("ldmatrix.sync.aligned.m8n8.x2.trans.shared.b16 {%0,%1}, [%2];\n"
        : "=r"(t[0]), "=r"(t[1])
        : "r"(smem_addr(sV, l & 7, (l >> 3) * 8)));   // rows 0-15, col8 = 0 (lanes 0-7), 8 (lanes 8-15)
    b[0] = t[0]; b[1] = t[1];
    mma(d, a, b, c);
    out[((g)*8 + 2*tig)*4 + 0] = d[0];
    out[((g)*8 + 2*tig+1)*4 + 0] = d[1];
    out[((g+8)*8 + 2*tig)*4 + 0] = d[2];
    out[((g+8)*8 + 2*tig+1)*4 + 0] = d[3];
}
