    float h[512]; cudaMemcpy(h, d, sizeof(h), cudaMemcpyDeviceToHost);
    float maxerr = 0; int bad = 0;
    for (int r = 0; r < 16; ++r) for (int n = 0; n < 8; ++n) {
        float ref = 0;
        for (int k = 0; k < 16; ++k) ref += Pv(r,k) * Vv(k,n);
        float got = h[(r*8+n)*4];
        float e = got > ref ? got-ref : ref-got;
        if (e > maxerr) maxerr = e;
        if (e > ref*0.01f && bad < 8) { printf("PV D[%d][%d] got %.2f ref %.2f\n", r, n, got, ref); bad++; }
    }
    printf("PV maxerr = %f (bad=%d)  [relative 1%% check]\n", maxerr, bad);
    cudaFree(d);
    return 0;
}
